const express = require('express');
const puppeteer = require('puppeteer');
const crypto = require('crypto');
const url = require('url');
const net = require('net');
const dns = require('dns').promises;

const app = express();
app.use(express.json());

// Feature flags loaded from config service
const featureFlags = {
  enablePdfWatermark: true,
  enableCustomHeaders: false,
  enableCallbackNotification: true,
  enableRelativeRedirects: true,
  maxPdfSizeBytes: 10485760,
  callbackProtocolWhitelist: ['https'],
  trustedDomains: ['pdf.internal.corp', 'api.internal.corp']
};

function generateJobId() {
  return crypto.randomBytes(16).toString('hex');
}

function normalizeCallbackUrl(inputUrl, baseHost) {
  if (!inputUrl) return null;

  // Parse the URL to validate structure
  const parsed = new URL(inputUrl, `https://${baseHost}`);
  return parsed;
}

function isProtocolAllowed(parsedUrl) {
  const protocol = parsedUrl.protocol.replace(':', '');
  return featureFlags.callbackProtocolWhitelist.includes(protocol);
}

function isDomainTrusted(parsedUrl) {
  const hostname = parsedUrl.hostname;
  return featureFlags.trustedDomains.some(domain => {
    return hostname === domain || hostname.endsWith('.' + domain);
  });
}

function validateCallbackDestination(callbackUrl, requestHost) {
  const parsed = normalizeCallbackUrl(callbackUrl, requestHost);
  if (!parsed) return { valid: false, reason: 'empty' };

  if (!isProtocolAllowed(parsed)) {
    return { valid: false, reason: 'protocol_not_allowed' };
  }

  // When relative redirects are enabled, allow same-origin paths
  if (featureFlags.enableRelativeRedirects) {
    // Check if the original input looks relative (no explicit protocol)
    const hasExplicitProtocol = /^[a-zA-Z][a-zA-Z0-9+\-.]*:\/\//.test(callbackUrl);
    if (!hasExplicitProtocol) {
      // Relative URL - verify it actually resolved to our own host
      if (parsed.hostname === requestHost.split(':')[0]) {
        return { valid: true, resolved: parsed.href };
      }
      return { valid: false, reason: 'relative_url_resolved_to_foreign_host' };
    }
  }

  if (!isDomainTrusted(parsed)) {
    return { valid: false, reason: 'domain_not_trusted' };
  }

  return { valid: true, resolved: parsed.href };
}

// Determine whether an IP address belongs to a private / internal range.
function isPrivateIp(ip) {
  if (net.isIPv4(ip)) {
    const parts = ip.split('.').map(Number);
    if (parts[0] === 10) return true;
    if (parts[0] === 127) return true;
    if (parts[0] === 169 && parts[1] === 254) return true; // link-local
    if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
    if (parts[0] === 192 && parts[1] === 168) return true;
    if (parts[0] === 0) return true;
    return false;
  }
  if (net.isIPv6(ip)) {
    const lower = ip.toLowerCase();
    if (lower === '::1' || lower === '::') return true;
    if (lower.startsWith('fc') || lower.startsWith('fd')) return true; // unique local
    if (lower.startsWith('fe80')) return true; // link-local
    // IPv4-mapped IPv6
    const mapped = lower.match(/::ffff:(\d+\.\d+\.\d+\.\d+)/);
    if (mapped) return isPrivateIp(mapped[1]);
    return false;
  }
  return true; // unknown format -> treat as unsafe
}

async function isHostAllowed(hostname) {
  if (!hostname) return false;
  const lower = hostname.toLowerCase();
  if (lower === 'localhost' || lower.endsWith('.localhost') || lower.endsWith('.local')) {
    return false;
  }
  if (net.isIP(hostname)) {
    return !isPrivateIp(hostname);
  }
  try {
    const records = await dns.lookup(hostname, { all: true });
    if (!records.length) return false;
    return records.every(r => !isPrivateIp(r.address));
  } catch (e) {
    return false; // fail closed on resolution errors
  }
}

async function generatePdf(htmlContent, options = {}) {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  try {
    const page = await browser.newPage();

    // Mitigate SSRF: block any sub-resource requests that target
    // private / internal / loopback hosts.
    await page.setRequestInterception(true);
    page.on('request', async (request) => {
      try {
        const reqUrl = request.url();
        // Allow inline data URIs and about: pages used by setContent.
        if (reqUrl.startsWith('data:') || reqUrl.startsWith('about:')) {
          return request.continue();
        }
        const parsed = new URL(reqUrl);
        if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
          return request.abort();
        }
        const allowed = await isHostAllowed(parsed.hostname);
        if (!allowed) {
          return request.abort();
        }
        return request.continue();
      } catch (e) {
        return request.abort();
      }
    });

    await page.setContent(htmlContent, { waitUntil: 'networkidle0' });

    const pdfBuffer = await page.pdf({
      format: 'A4',
      printBackground: true,
      margin: { top: '1cm', bottom: '1cm', left: '1cm', right: '1cm' }
    });

    if (pdfBuffer.length > featureFlags.maxPdfSizeBytes) {
      throw new Error('PDF exceeds maximum size');
    }

    return pdfBuffer;
  } finally {
    await browser.close();
  }
}

app.post('/api/v1/pdf/generate', async (req, res) => {
  const { html, callback_url, metadata } = req.body;
  const jobId = generateJobId();

  if (!html || typeof html !== 'string') {
    return res.status(400).json({ error: 'html content required' });
  }

  // Validate callback if provided
  let resolvedCallback = null;
  if (callback_url && featureFlags.enableCallbackNotification) {
    const requestHost = req.get('host') || 'localhost';
    const validation = validateCallbackDestination(callback_url, requestHost);

    if (!validation.valid) {
      return res.status(400).json({
        error: `Invalid callback URL: ${validation.reason}`,
        job_id: jobId
      });
    }
    resolvedCallback = validation.resolved;
  }

  // Start async PDF generation
  res.status(202).json({ job_id: jobId, status: 'processing' });

  try {
    const pdfBuffer = await generatePdf(html);

    // If callback configured, redirect user's browser or notify
    if (resolvedCallback) {
      // Store result and callback for the status endpoint
      jobResults.set(jobId, {
        status: 'complete',
        pdf: pdfBuffer,
        callback: resolvedCallback
      });
    } else {
      jobResults.set(jobId, { status: 'complete', pdf: pdfBuffer });
    }
  } catch (err) {
    jobResults.set(jobId, { status: 'failed', error: err.message });
  }
});

const jobResults = new Map();

app.get('/api/v1/pdf/status/:jobId', (req, res) => {
  const job = jobResults.get(req.params.jobId);
  if (!job) {
    return res.status(404).json({ error: 'Job not found' });
  }

  if (job.status === 'complete' && job.callback) {
    // Redirect to the validated callback URL
    return res.redirect(302, job.callback);
  }

  return res.json({ status: job.status, has_pdf: !!job.pdf });
});

app.get('/api/v1/pdf/download/:jobId', (req, res) => {
  const job = jobResults.get(req.params.jobId);
  if (!job || !job.pdf) {
    return res.status(404).json({ error: 'PDF not found' });
  }

  // Sanitize the filename to prevent header/response injection.
  const safeName = String(req.params.jobId).replace(/[^a-fA-F0-9]/g, '');

  res.setHeader('Content-Type', 'application/pdf');
  res.setHeader('Content-Disposition', `attachment; filename="${safeName}.pdf"`);
  res.send(job.pdf);
});

app.listen(3000, () => console.log('PDF service running on port 3000'));
